<?php
namespace WGMM;

/** Site-level controls reuse Store authorization and concurrency checks. */
final class Admin {
    private const PAGES=['wgmm-settings'=>'Overview','wgmm-companies'=>'Companies','wgmm-users'=>'Users & Access','wgmm-campaigns'=>'Campaigns & Files','wgmm-activity'=>'Activity','wgmm-product-settings'=>'Settings'];
    public static function menu(): void {
        add_menu_page('Social Media Magnet Pro','Social Media Magnet Pro','manage_options','wgmm-settings',[__CLASS__,'page'],'dashicons-schedule',26.5);
        foreach(self::PAGES as $slug=>$label){add_submenu_page('wgmm-settings',$label,$label,'manage_options',$slug,[__CLASS__,'page']);}
        add_management_page('Message Matrix Pro','Message Matrix Pro','manage_options','wgmm-settings',[__CLASS__,'page']);
        remove_submenu_page('tools.php','wgmm-settings');
    }
    private static function require_admin(): void {if(!current_user_can('manage_options')){throw new \RuntimeException('Administrator access required.',403);}}
    private static function url(string $page='wgmm-settings',int $id=0): string {$args=['page'=>isset(self::PAGES[$page])?$page:'wgmm-settings'];if($id){$args['matrix_company']=$id;}return add_query_arg($args,admin_url('admin.php'));}
    private static function link(string $label,string $url): string {return $url?'<a class="button" href="'.esc_url($url).'">'.esc_html($label).'</a>':'<span class="description">Select the workspace page in Settings.</span>';}
    public static function workspace_url(int $id): string {
        $page=absint(get_option('wgmm_settings',[])['workspace_page_id']??0);
        if(!$page){$matches=[];foreach(get_posts(['post_type'=>'page','post_status'=>['publish','private'],'s'=>'message_matrix_pro','posts_per_page'=>20]) as $p){if(has_shortcode($p->post_content??'','message_matrix_pro')){$matches[]=(int)$p->ID;}}if(count($matches)===1){$page=$matches[0];}}
        $p=$page?get_post($page):null;
        if(!$p||$p->post_type!=='page'||!in_array($p->post_status,['publish','private'],true)||!has_shortcode($p->post_content??'','message_matrix_pro')){return '';}
        return add_query_arg('matrix_company',$id,get_permalink($page));
    }
    public static function page(): void {
        if(!current_user_can('manage_options')){wp_die('Administrator access required.');}
        $screen=sanitize_key(wp_unslash($_GET['page']??'wgmm-settings'));if(!isset(self::PAGES[$screen])){$screen='wgmm-settings';}
        echo '<div class="wrap wgmm-admin"><h1>Social Media Magnet Pro · '.esc_html(self::PAGES[$screen]).'</h1><style>.wgmm-admin .wgmm-card{background:#fff;border:1px solid #c3d4df;padding:20px;margin:18px 0;max-width:1200px}.wgmm-admin .wgmm-actions{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:12px 0}.wgmm-admin .wgmm-scroll{overflow-x:auto}.wgmm-admin table{min-width:600px}.wgmm-admin td{vertical-align:top}.wgmm-admin td small{display:block}.wgmm-admin pre{white-space:pre-wrap;overflow-wrap:anywhere}.wgmm-admin summary{cursor:pointer;font-weight:600;padding:10px 0}.wgmm-admin details>summary:after{content:" ⌄"}.wgmm-admin details[open]>summary:after{content:" ⌃"}.wgmm-admin .wgmm-logo{max-width:100px;max-height:64px;object-fit:contain}.wgmm-admin .wgmm-company-heading{display:flex;gap:14px;align-items:center}</style>';
        if(isset($_GET['wgmm_message'])){echo '<div class="notice notice-info"><p>'.esc_html(sanitize_text_field(wp_unslash($_GET['wgmm_message']))).'</p></div>';}
        try{
            if($screen==='wgmm-product-settings'){self::settings();}
            elseif($screen==='wgmm-activity'){self::activity();}
            else{$companies=Store::listing();$id=absint($_GET['matrix_company']??0);if($screen==='wgmm-settings'){self::overview($companies);}else{self::picker($screen,$companies,$id);if($id){$row=Store::access($id);self::heading($row);if($screen==='wgmm-users'){self::users($row);}else{self::campaigns($row);}}else{echo '<p>Select a company above to inspect its saved work and access.</p>';}}}
        }catch(\Throwable $e){echo '<div class="notice notice-error"><p>'.esc_html($e->getCode()===500?'Company data could not be loaded. No change has been confirmed.':$e->getMessage()).'</p></div>';}
        echo '</div>';
    }
    private static function overview(array $companies): void {
        echo '<p>Manage companies, user access and saved campaign work. Routine campaign development stays with company Owners and Strategists.</p><div class="wgmm-actions">';foreach(['wgmm-companies','wgmm-users','wgmm-campaigns','wgmm-product-settings'] as $p){echo self::link(self::PAGES[$p],self::url($p));}
        echo '</div><div class="wgmm-card"><h2>Company workspaces</h2><div class="wgmm-scroll"><table class="widefat striped"><thead><tr><th>Company</th><th>Access</th><th>Saved work</th><th>Last updated · Central Time</th><th>Actions</th></tr></thead><tbody>';
        foreach($companies as $c){$r=Store::access((int)$c['id']);$d=$r['document'];echo '<tr><td><strong>'.esc_html($r['title']).'</strong></td><td>'.esc_html($r['writable']?'Active':'Read-only').'</td><td>'.count($d['campaigns']).' campaigns · '.count($d['assets']).' assets</td><td>'.esc_html(self::central($r['updated_at'])).'</td><td>'.self::link('Manage company',self::url('wgmm-companies',$r['id'])).'</td></tr>';}
        if(!$companies){echo '<tr><td colspan="5">No workspaces yet. Create a company in Settings.</td></tr>';}echo '</tbody></table></div><p class="description">Up to 200 companies are shown. Counts reflect saved records, not completion of the campaign.</p></div>';
    }
    private static function picker(string $screen,array $companies,int $id): void {
        echo '<form method="get" class="wgmm-actions"><input type="hidden" name="page" value="'.esc_attr($screen).'"><label for="wgmm-company">Company </label><select id="wgmm-company" name="matrix_company"><option value="0">Select a company</option>';foreach($companies as $c){echo '<option value="'.(int)$c['id'].'"'.selected($id,(int)$c['id'],false).'>'.esc_html($c['title']).'</option>';}echo '</select><button class="button button-primary">Open company</button></form>';
    }
    private static function heading(array $r): void {
        echo '<div class="wgmm-company-heading">';$logo=$r['document']['brand']['logo_url']??'';if($logo){echo '<img class="wgmm-logo" src="'.esc_url($logo).'" alt="'.esc_attr($r['title'].' logo').'">';}echo '<h2>'.esc_html($r['title']).'</h2></div><div class="wgmm-actions">'.self::link('Open customer workspace',self::workspace_url($r['id'])).self::link('Manage users',self::url('wgmm-users',$r['id'])).self::link('Campaigns & files',self::url('wgmm-campaigns',$r['id'])).'</div>';
        $u=get_userdata($r['owner_id']);echo '<p><strong>Owner:</strong> '.esc_html($u?$u->display_name:'Unavailable user').' · <strong>Foundation:</strong> '.esc_html($r['approved_version']?'Approved snapshot saved':'Not approved').' · <strong>Product access:</strong> '.esc_html($r['writable']?'Active':'Read-only').'</p>';
    }
    private static function users(array $r): void {
        echo '<div class="wgmm-card"><h3>Company team</h3><p>Roles apply to this company only. Strategists can upload/download documents, develop campaigns and review content. Reviewers can inspect and approve content without editing the Brand foundation.</p><div class="wgmm-scroll"><table class="widefat striped"><thead><tr><th>User</th><th>Role</th><th>Manage access</th><th>Support</th></tr></thead><tbody>';
        foreach(Store::members($r['id']) as $m){$u=get_userdata($m['user_id']);echo '<tr><td>'.esc_html($m['name']).'<small>'.esc_html($u?$u->user_email:'Unavailable account').'</small></td><td>'.esc_html(ucfirst($m['role'])).'</td><td>';if($m['user_id']===$r['owner_id']){echo '<span class="description">Owner protected. Ownership transfer is separate from team editing.</span>';}elseif($u){self::team_form($r,$u->user_email,$m['role'],false);}echo '</td><td>';self::switch_link($r,$u);echo '</td></tr>';}
        echo '</tbody></table></div><h3>Add an existing site user</h3>';self::team_form($r,'','reviewer',true);echo '<p class="description">This revision manages existing logins. Invitation emails and courseware provisioning are pending; no course levels are changed here.</p></div>';
    }
    private static function team_form(array $r,string $email,string $role,bool $new): void {
        echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'" class="wgmm-actions">';wp_nonce_field('wgmm_admin_team_'.$r['id']);echo '<input type="hidden" name="action" value="wgmm_admin_team"><input type="hidden" name="matrix_company" value="'.$r['id'].'"><input type="hidden" name="revision" value="'.$r['revision'].'">';
        echo $new?'<label>Existing user email <input type="email" name="email" required></label>':'<input type="hidden" name="email" value="'.esc_attr($email).'">';echo '<label>Role <select name="role">';foreach(['strategist','reviewer','contributor','viewer'] as $v){echo '<option value="'.$v.'"'.selected($role,$v,false).'>'.esc_html(ucfirst($v)).'</option>';}echo '</select></label><button class="button button-primary" name="operation" value="save">'.($new?'Add company access':'Save role').'</button>';if(!$new){echo '<button class="button" name="operation" value="remove">Remove company access</button>';}echo '</form>';
    }
    private static function switch_link(array $r,$u): void {
        if(!$u||$u->ID===get_current_user_id()){echo '<span class="description">Current account</span>';return;}
        if(is_callable(['\\user_switching','maybe_switch_url'])){$url=\user_switching::maybe_switch_url($u);if($url){$target=self::workspace_url($r['id']);if($target){$url=add_query_arg('redirect_to',$target,$url);}echo self::link('Act as user',$url);return;}}
        echo '<span class="description">User Switching must be active and permit this account. Its switch-back control returns to administrator.</span>';
    }
    private static function campaigns(array $r): void {
        $d=$r['document'];$cells=array_column($d['cells'],null,'id');$verticals=array_column($d['audiences'],null,'id');$buckets=array_column($d['buckets'],null,'id');echo '<div class="wgmm-card"><h3>Campaigns & saved content</h3>';
        foreach($d['campaigns'] as $c){$assets=array_values(array_filter($d['assets'],static fn($a)=>$a['campaign_id']===$c['id']));$approved=count(array_filter($assets,static fn($a)=>$a['status']==='approved'));echo '<details><summary>'.esc_html($c['title']).' · '.count($assets).' assets · '.$approved.' approved</summary><p>'.esc_html((new \DateTimeImmutable($c['start']))->format('m/d/Y')).' · '.(int)$c['days'].' days</p><p>'.esc_html($c['objective']).'</p><div class="wgmm-scroll"><table class="widefat striped"><thead><tr><th>Title / copy</th><th>Channel</th><th>Content Focus</th><th>Vertical / Bucket</th><th>Status</th></tr></thead><tbody>';
            foreach($assets as $a){$cell=$cells[$a['cell_id']]??[];echo '<tr><td><details><summary>'.esc_html($a['title']).'</summary><pre>'.esc_html($a['copy']).'</pre>'.(!empty($a['review_notes'])?'<p><strong>Requested changes:</strong> '.esc_html($a['review_notes']).'</p>':'').'</details><small>'.esc_html($a['type']==='visual_brief'?'Image instructions (not an image file)':ucfirst($a['type'])).'</small></td><td>'.esc_html($a['channel']).'</td><td>'.esc_html($a['role']).'</td><td>'.esc_html($verticals[$cell['audience_id']??'']['name']??'Not linked').'<small>'.esc_html($buckets[$cell['bucket_id']??'']['name']??'Not linked').'</small></td><td>'.esc_html(str_replace('_',' ',$a['status'])).'</td></tr>';}
            if(!$assets){echo '<tr><td colspan="5">No saved content yet.</td></tr>';}echo '</tbody></table></div></details>';}
        if(!$d['campaigns']){echo '<p>No campaigns saved yet.</p>';}echo '<h3>Company documents</h3><ul>';foreach(Sources::links($r) as $kind=>$source){echo '<li><a href="'.esc_url($source['download_url']).'">'.esc_html(Sources::TYPES[$kind].' · '.$source['filename']).'</a></li>';}if(!$d['foundation_sources']){echo '<li>No Strategy Canvas or Brand Dyno attached. These inputs are optional.</li>';}echo '</ul><p class="description">Downloads recheck access. Real image generation and complete publishing packages will arrive in a later revision.</p></div>';
    }
    public static function change_team(int $id,int $revision,string $email,string $role,string $operation): array {
        self::require_admin();Domain::choice($operation,['save','remove']);if(!is_email($email)){throw new \InvalidArgumentException('Enter a valid existing user email.');}
        $out=Store::team($id,$revision,$email,$role,$operation==='remove');$u=get_user_by('email',$email);self::record($id,$operation==='remove'?'company_access_removed':'company_role_saved',['user_id'=>$u?(int)$u->ID:0,'role'=>$role]);return $out;
    }
    public static function team(): void {
        $id=absint($_POST['matrix_company']??0);try{self::require_admin();check_admin_referer('wgmm_admin_team_'.$id);self::change_team($id,absint($_POST['revision']??0),sanitize_email(wp_unslash($_POST['email']??'')),sanitize_key($_POST['role']??''),sanitize_key($_POST['operation']??''));self::redirect('Company access saved.','wgmm-users',$id);}catch(\Throwable $e){self::redirect($e->getCode()===500?'Access change could not be confirmed. Reload before retrying.':$e->getMessage(),'wgmm-users',$id);}
    }
    private static function record(int $id,string $action,array $details=[]): void {$log=get_option('wgmm_admin_activity',[]);if(!is_array($log)){$log=[];}array_unshift($log,['company'=>$id,'actor'=>get_current_user_id(),'action'=>$action,'details'=>$details,'time'=>gmdate('Y-m-d H:i:s')]);update_option('wgmm_admin_activity',array_slice($log,0,100),false);}
    private static function activity(): void {
        echo '<div class="wgmm-card"><h2>Recent administrative changes</h2><p class="description">Latest 100 changes made through these controls; not a full system audit log.</p><table class="widefat striped"><thead><tr><th>Central Time</th><th>Administrator</th><th>Company ID</th><th>Action</th><th>Target user / role</th></tr></thead><tbody>';foreach((array)get_option('wgmm_admin_activity',[]) as $e){$u=get_userdata((int)$e['actor']);echo '<tr><td>'.esc_html(self::central($e['time'])).'</td><td>'.esc_html($u?$u->display_name:'Unavailable user').'</td><td>'.(int)$e['company'].'</td><td>'.esc_html(str_replace('_',' ',$e['action'])).'</td><td>'.(int)($e['details']['user_id']??0).' '.esc_html($e['details']['role']??'').'</td></tr>';}echo '</tbody></table></div>';
    }
    private static function settings(): void {
        $s=get_option('wgmm_settings',[]);echo '<div class="wgmm-card"><h2>Product settings</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('wgmm_settings');echo '<input type="hidden" name="action" value="wgmm_settings"><p><label>WishList Message Matrix Pro level IDs<br><input class="regular-text" name="level_ids" value="'.esc_attr(implode(',',$s['level_ids']??[])).'"></label></p><p>Comma-separated numeric IDs. Leave blank for administrator-provisioned tests. Courseware enrollment is not yet connected.</p><p><label>Company seat limit <input type="number" name="seat_limit" min="1" max="50" value="'.esc_attr($s['seat_limit']??5).'"></label></p><p><label for="wgmm-workspace-page">Message Matrix workspace page</label><br>';wp_dropdown_pages(['name'=>'workspace_page_id','id'=>'wgmm-workspace-page','selected'=>absint($s['workspace_page_id']??0),'show_option_none'=>'Auto-detect a single shortcode page','option_none_value'=>0,'post_status'=>['publish','private']]);echo '</p><p class="description">Select a page containing [message_matrix_pro]. The plugin checks company access. Page-level membership protection can separately block invited teammates and needs onboarding UAT.</p>';submit_button('Save product settings');echo '</form></div><div class="wgmm-card"><h2>Create company workspace</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('wgmm_create');echo '<input type="hidden" name="action" value="wgmm_create"><p><label>Company name <input name="title" required maxlength="200"></label></p><p><label>Existing owner email <input name="owner_email" type="email" required></label></p><p><label><input type="checkbox" name="complimentary" value="1"> Grant complimentary Message Matrix Pro access</label></p>';submit_button('Create company workspace');echo '</form><p class="description">Existing logins only. No passwords, invitations, course levels or Pro Analytics data are changed.</p></div>';
    }
    public static function save(): void {
        if(!current_user_can('manage_options')){wp_die('Administrator access required.');}check_admin_referer('wgmm_settings');$ids=array_values(array_filter(array_map('trim',explode(',',sanitize_text_field(wp_unslash($_POST['level_ids']??''))))));foreach($ids as $id){if(!ctype_digit($id)){wp_die('WishList level IDs must be numeric.');}}
        $page=absint($_POST['workspace_page_id']??0);$p=$page?get_post($page):null;if($page&&(!$p||$p->post_type!=='page'||!in_array($p->post_status,['publish','private'],true)||!has_shortcode($p->post_content??'','message_matrix_pro'))){self::redirect('Select a published page containing the Message Matrix Pro shortcode.','wgmm-product-settings');}
        $s=get_option('wgmm_settings',[]);$s['level_ids']=array_values(array_unique($ids));$s['seat_limit']=max(1,min(50,(int)($_POST['seat_limit']??5)));$s['workspace_page_id']=$page;update_option('wgmm_settings',$s,false);self::record(0,'product_settings_saved');self::redirect('Product settings saved.','wgmm-product-settings');
    }
    public static function create(): void {
        if(!current_user_can('manage_options')){wp_die('Administrator access required.');}check_admin_referer('wgmm_create');try{$u=get_user_by('email',sanitize_email(wp_unslash($_POST['owner_email']??'')));if(!$u){throw new \InvalidArgumentException('The owner needs an existing site login.');}$id=Store::create(Domain::required(wp_unslash($_POST['title']??''),200),(int)$u->ID,($_POST['complimentary']??'')==='1');self::record($id,'company_created',['user_id'=>(int)$u->ID]);self::redirect('Company workspace created.','wgmm-companies',$id);}catch(\Throwable $e){self::redirect($e->getCode()===500?'The workspace could not be created.':$e->getMessage(),'wgmm-product-settings');}
    }
    private static function central(string $date): string {return (new \DateTimeImmutable($date,new \DateTimeZone('UTC')))->setTimezone(new \DateTimeZone('America/Chicago'))->format('m/d/Y g:i A T');}
    private static function redirect(string $message,string $page='wgmm-settings',int $id=0): void {wp_safe_redirect(add_query_arg('wgmm_message',$message,self::url($page,$id)));exit;}
}
